                    const auto lhsStartLoc = clang::Lexer::getLocForEndOfToken(
                        CO->getQuestionLoc(), 0, SM, LO);
                    const auto lhsEndLoc = CO->getColonLoc();
                    const auto lhsRange = clang::CharSourceRange(
                        { lhsStartLoc, lhsEndLoc }, false);
                    const auto lhs = util::trim_str(mRewriter.getRewrittenText(lhsRange));

                    const auto rhsStartLoc = clang::Lexer::getLocForEndOfToken(
                        SM.getExpansionLoc(CO->getColonLoc()), 0, SM, LO);
                    const auto rhsEndLoc = findNextTokenLocation(
                        SM.getExpansionLoc(CO->getEndLoc()), clang::tok::semi);
                    const auto rhsRange = clang::CharSourceRange(
                        { rhsStartLoc, rhsEndLoc }, false);
                    const auto rhs = util::trim_str(mRewriter.getRewrittenText(rhsRange));
                    std::cout << std::format(
                        "conditionalOperator:"
                        "\n  lhsStartLoc: {}"
                        "\n  lhsEndLoc: {}"
                        "\n  rhsStartLoc: {}"
                        "\n  rhsEndLoc: {}\n"
                        , locStr(lhsStartLoc)
                        , locStr(lhsEndLoc)
                        , locStr(rhsStartLoc)
                        , locStr(rhsEndLoc));

                    // Instrument the code as follows:
                    const auto probeText = std::format(
                        "/*PRB #{}*/{} ? {} : {}"
                        , gProbeIndex++
                        , condString
                        , lhs
                        , rhs);
                    // Replace the entire ConditionalOperator (ternary) expression.
                    mRewriter.ReplaceText(
                        {startLoc, rhsEndLoc.getLocWithOffset(-1)},
                        probeText);
                }
                // Returning true continues the traversal.
                return true;
            }

            //! Visitor callback for 'clang::IfStmt'.
            bool VisitIfStmt(const clang::IfStmt *IS) const {
                if (const auto& [SR, condString, rightPad] =
                        getConditionSourceFromStmt(IS); !condString.empty()) {
                    const auto& SM = mContext.getSourceManager();
                    const auto& [startLoc, lineNumber,
                        sourcePath, functionName] =
                            getProbeInfo(SM, SR, mCurrentFunction);
                    // Replace the condition string.
                    const auto probeText = std::format(
                        "/*PRB #{}*/{}"
                        , gProbeIndex++
                        , condString);
                    mRewriter.ReplaceText(SR, probeText);
                }
                // Returning true continues the traversal.
                return true;
            }

            //! Visitor callback for 'clang::WhileStmt'.
            bool VisitWhileStmt(const clang::WhileStmt *WS) const {
                if (WS->getCond()) {
                    if (const auto& [SR, condString, rightPad] =
                        getConditionSourceFromStmt(WS); !condString.empty()) {
                        const auto& SM = mContext.getSourceManager();
                        const auto& [startLoc, lineNumber,
                            sourcePath, functionName] =
                                getProbeInfo(SM, SR, mCurrentFunction);
                        // Replace the condition string.
                        const auto probeText = std::format(
                            "/*PRB #{}*/{}"
                            , gProbeIndex++
                            , condString);
                        mRewriter.ReplaceText(SR, probeText);
                    }
                }
                // Returning true continues the traversal.
                return true;
            }

            //! Visitor pattern callback for 'clang::DoStmt'.
            bool VisitDoStmt(const clang::DoStmt *DS) const {
                if (DS->getCond()) {
                    if (const auto& [SR, condString, rightPad] =
                        getConditionSourceFromStmt(DS); !condString.empty()) {
                        const auto& SM = mContext.getSourceManager();
                        const auto& [startLoc, lineNumber,
                            sourcePath, functionName] =
                                getProbeInfo(SM, SR, mCurrentFunction);
                        // Replace the condition string.
                        const auto probeText = std::format(
                            "/*PRB #{}*/{}"
                            , gProbeIndex++
                            , condString);
                        mRewriter.ReplaceText(SR, probeText);
                    }
                }
                // Returning true continues the traversal.
                return true;
            }

            //! Visitor callback for 'clang::ForStmt'.
            bool VisitForStmt(const clang::ForStmt *FS) const {
                if (FS->getCond()) {
                    if (const auto& [SR, condString, rightPad] =
                        getConditionSourceFromStmt(FS); !condString.empty()) {
                        const auto& SM = mContext.getSourceManager();
                        const auto& [startLoc, lineNumber,
                            sourcePath, functionName] =
                                getProbeInfo(SM, SR, mCurrentFunction);
                        // Replace the condition string.
                        const auto probeText = std::format(
                            "(/*PRB #{}*/{}){}"
                            , gProbeIndex++
                            , util::trim_str(condString)
                            , rightPad ? " " : "");
                        mRewriter.ReplaceText(SR, probeText);
                    }
                }
                // Returning true continues the traversal.
                return true;
            }

        private:
            //! Source Location printer.
            std::string locStr(clang::SourceLocation loc) const {
                return loc.printToString(mContext.getSourceManager());
            }

            [[nodiscard]] auto getConditionSourceFromStmt(const clang::Stmt* stmt) const ->
                std::tuple<clang::CharSourceRange, std::string, bool> {
                const auto& SM = mContext.getSourceManager();
                const auto& [SR, rightPad] = getConditionSourceRange(stmt);
                if (SM.isWrittenInSameFile(SR.getBegin(), SR.getEnd())) {
                    // Get the text *after* taking prior rewrites into account.
                    return { SR, mRewriter.getRewrittenText(SR), rightPad };
                }
                return {};
            }

            //! Helper function to search for token starting from location <code>startLoc</code>.
            [[nodiscard]] auto findNextTokenLocation(
                const clang::SourceLocation& startLoc, const auto& token) const ->
                clang::SourceLocation {
                const auto& SM = mContext.getSourceManager();
                const auto& LO = mContext.getLangOpts();
                // create a lexer to find the end of the statement/eof.
                const auto lexer = std::make_unique<clang::Lexer>(
                    startLoc, LO, SM.getCharacterData(startLoc),
                    SM.getCharacterData(clang::Lexer::getLocForEndOfToken(startLoc, 0, SM, LO)),
                    SM.getCharacterData(SM.getLocForEndOfFile(SM.getMainFileID())));
                //lexer->ExtendedTokenMode = 1; // interpret comments as tokens - ignore whitespace.
                clang::Token tok;
                do {
                    lexer->LexFromRawLexer(tok);
                    if (tok.is(token)) {
                        // return the token location.
                        return tok.getLocation();
                    }
                    // std::cout << "Token text: " << clang::Lexer::getSpelling(tok, SM, LO) << "\n";
                } while (!tok.is(clang::tok::eof));
                return {};
            }

            auto getConditionSourceRange(const clang::Stmt* stmt) const ->
                std::pair <clang::CharSourceRange, bool> {
                const auto& SM = mContext.getSourceManager();
                const auto& LO = mContext.getLangOpts();

                if (const auto IS = dyn_cast<clang::IfStmt>(stmt)) {
                    // Location after the '('.
                    const auto afterLParenLoc = IS->getCond()->getBeginLoc();
                    // Location before the ')'.
                    const auto beforeRParenLoc = IS->getRParenLoc();
                    const auto conditionRange = clang::CharSourceRange(
                        { afterLParenLoc, beforeRParenLoc }, false);
                    return { SM.getExpansionRange(conditionRange), false };
                } else if (const auto WS = dyn_cast<clang::WhileStmt>(stmt)) {
                    // Location after the '('.
                    const auto afterLParenLoc = WS->getCond()->getBeginLoc();
                    // Location before the ')'.
                    const auto beforeRParenLoc = WS->getRParenLoc();
                    const auto conditionRange = clang::CharSourceRange(
                        { afterLParenLoc, beforeRParenLoc }, false);
                    return { SM.getExpansionRange(conditionRange), false };
                } else if (const auto DS = dyn_cast<clang::DoStmt>(stmt)) {
                    // Location after the '('.
                    const auto afterLParenLoc = DS->getCond()->getBeginLoc();
                    // Location before the ')'.
                    const auto beforeRParenLoc = DS->getRParenLoc();
                    const auto conditionRange = clang::CharSourceRange(
                        { afterLParenLoc, beforeRParenLoc }, false);
                    return { SM.getExpansionRange(conditionRange), false };
                } else if (const auto FS = dyn_cast<clang::ForStmt>(stmt)) {
                    // There are 2 ways to determine the start of the condition
                    // (this is the location past the first semicolon).
                    // -------------------------------------------------------------------
                    // If an init section is present, There appears to be a lexer bug where
                    // 'FS->getInit()->getEndLoc()' points to 'clang::tok::semi' instead of
                    // pointing to the start token of the init section (see below).
                    //
                    // - Initializer with locally declared type loop variable:
                    //   for (int a = 30 /*FOO*/ ; a<50; ++a) {}
                    //                           ^--- FS->Init()->getEndLoc() points here.
                    //                ^--- FS->Init()->getEndLoc() should point here.
                    // - Initializer with externally declared type loop variable:
                    //   for (a = 30 /*FOO*/ ; a<3; ++a) {}
                    //            ^--- FS->Init()->getEndLoc() points here.
                    // -------------------------------------------------------------------
                    clang::SourceLocation afterFirstSemiLoc =
                        clang::Lexer::findLocationAfterToken(
                            FS->getLParenLoc(), clang::tok::semi,
                                SM, LO, false);
                    if (FS->getInit()) {
                        clang::Token token;
                        auto locationStr = locStr(FS->getInit()->getEndLoc());
                        clang::Lexer::getRawToken(FS->getInit()->getEndLoc(), token, SM, LO);
                        if (token.is(clang::tok::semi)) {
                            afterFirstSemiLoc = token.getLocation().getLocWithOffset(1);
                        } else if (SM.isMacroBodyExpansion(FS->getInit()->getEndLoc())) {
                            const auto tokenLen = clang::Lexer::MeasureTokenLength(FS->getInit()->getEndLoc(), SM, LO);
                            afterFirstSemiLoc = SM.getExpansionLoc(FS->getInit()->getEndLoc()).getLocWithOffset(
                                static_cast<clang::SourceLocation::IntTy>(tokenLen));
                        } else {
                            if (const auto tok = clang::Lexer::findNextToken(token.getLocation(), SM, LO); tok) {
                                const auto tokenLen = clang::Lexer::MeasureTokenLength(tok->getLocation(), SM, LO);
                                afterFirstSemiLoc = tok->getLocation().getLocWithOffset(
                                    static_cast<clang::SourceLocation::IntTy>(tokenLen));
                            }
                        }
                        locationStr = locStr(afterFirstSemiLoc);
                    }

                    // Get the last token of the condition,
                    // clang::ForStmt have mandatory condition.
                    if (const auto cond = FS->getCond(); cond) {
                        const auto condLastTokenLoc = cond->getEndLoc();
                        // Get the next token, which should be the second semi.
                        if (const auto secondSemiToken =
                            clang::Lexer::findNextToken(condLastTokenLoc, SM, LO); secondSemiToken) {
                            const auto beforeSecondSemiLoc = secondSemiToken->getLocation();
                            std::cout << std::format(
                                "forStmt:"
                                "\n  AfterFirstSemi: {}"
                                "\n  BeforeSecondSemi: {}\n"
                                , locStr(afterFirstSemiLoc)
                                , locStr(beforeSecondSemiLoc));
                            const auto conditionRange = clang::CharSourceRange(
                                { afterFirstSemiLoc, beforeSecondSemiLoc }, false);
                            // macro flags used to add extra spaces around the condition.
                            return { SM.getExpansionRange(conditionRange),
                                secondSemiToken->isNot(clang::tok::semi) };
                        }
                    }
                    // invalid return here.
                    return {};
                } else if (auto CO = dyn_cast<clang::ConditionalOperator>(stmt)) {
                    const auto condRange = SM.getExpansionRange(CO->getCond()->getSourceRange());
                    if (CO->getBeginLoc().isMacroID()) {
